import { ApiClient } from "./api-client";
import { CheckoutModal } from "./modal";
import { VerificationPoller } from "./polling";
import { CheckoutStateMachine } from "./state-machine";
import type {
  BootstrapPayload,
  CheckoutErrorPayload,
  PayIslandCheckoutOptions,
  TransactionPayload,
  VerificationPayload,
} from "./types";
import {
  CheckoutError,
  extractBankTransfer,
  extractStatus,
  extractTransaction,
  getPollDelay,
  normalizeStatus,
  resolveApiBaseUrl,
  validateReference,
} from "./utils";

export type {
  PayIslandCheckoutOptions,
  CheckoutErrorPayload,
  TransactionPayload,
  VerificationPayload,
};

interface ActiveCheckout {
  options: PayIslandCheckoutOptions;
  reference: string;
  api?: ApiClient;
  modal: CheckoutModal;
  poller: VerificationPoller;
  machine: CheckoutStateMachine;
  bootstrap?: BootstrapPayload;
  successCalled: boolean;
  errorCalled: boolean;
  closeCalled: boolean;
  cardFrameMessageHandler?: (event: MessageEvent) => void;
}

let active: ActiveCheckout | undefined;

export function open(options: PayIslandCheckoutOptions): void {
  close(false);

  let reference: string;
  try {
    reference = validateReference(options?.reference);
  } catch (error) {
    const payload = toErrorPayload(error);
    options?.onError?.(payload);
    renderValidationError(options, payload);
    return;
  }

  let api: ApiClient;
  try {
    api = new ApiClient(resolveApiBaseUrl(options.__apiBaseUrl));
  } catch (error) {
    const payload = toErrorPayload(error);
    options.onError?.(payload);
    renderValidationError(options, payload);
    return;
  }

  const machine = new CheckoutStateMachine({
    reference,
    theme: options.theme ?? {},
    status: "idle",
  });
  const poller = new VerificationPoller();
  const modal = new CheckoutModal({
    container: options.container,
    theme: options.theme ?? {},
    onClose: (reason) => close(reason === "user"),
    onRetry: () => void bootstrapActive(),
    onChannelSelected: (channel) => {
      if (active?.bootstrap) {
        active.machine.context.selectedChannel = channel;
        active.modal.renderCheckout(
          active.bootstrap,
          active.options.channels,
          active.machine.context.status,
        );
        void initializeActiveChannel(channel);
      }
    },
    onPaymentStarted: () => beginActiveStatusChecks(),
    onRefreshStatus: () => void refreshActiveStatus(),
  });

  active = {
    options,
    reference,
    api,
    modal,
    poller,
    machine,
    successCalled: false,
    errorCalled: false,
    closeCalled: false,
  };
  active.cardFrameMessageHandler = handleCardFrameMessage;
  if (typeof window !== "undefined") {
    window.addEventListener("message", active.cardFrameMessageHandler);
  }

  modal.mount();
  void bootstrapActive();
}

export function close(callCallback = true): void {
  if (!active) return;

  const checkout = active;
  active = undefined;
  checkout.poller.stop();
  checkout.machine.send({ type: "CLOSE" });
  if (typeof window !== "undefined" && checkout.cardFrameMessageHandler) {
    window.removeEventListener("message", checkout.cardFrameMessageHandler);
  }
  checkout.modal.destroy();
  checkout.api?.setCheckoutToken(undefined);
  checkout.bootstrap = undefined;

  if (callCallback && !checkout.closeCalled) {
    checkout.closeCalled = true;
    checkout.options.onClose?.();
  }
}

async function bootstrapActive(): Promise<void> {
  const checkout = active;
  if (!checkout || !checkout.api) return;

  checkout.poller.stop();
  checkout.machine.send({ type: "LOAD" });
  checkout.modal.renderLoading();

  try {
    const response = await checkout.api.bootstrap(checkout.reference);
    if (active !== checkout) return;

    checkout.bootstrap = response.data;
    checkout.machine.context.bootstrap = response.data;
    checkout.machine.context.checkoutToken = response.checkoutToken;
    checkout.api.setCheckoutToken(response.checkoutToken);

    const hasAvailableChannel = checkout.modal.renderCheckout(
      response.data,
      checkout.options.channels,
    );
    if (!hasAvailableChannel) {
      checkout.machine.send({ type: "FAIL" });
      callErrorOnce({
        code: "no_available_channels",
        message: "No available payment channels for this checkout.",
      });
      return;
    }

    handlePayload(response.data, false);
  } catch (error) {
    if (active !== checkout) return;
    const payload = toErrorPayload(error);
    checkout.machine.context.error = payload;
    checkout.machine.send({ type: "FAIL" });
    checkout.modal.renderError(payload);
    callErrorOnce(payload);
  }
}

async function initializeActiveChannel(channel: string): Promise<void> {
  const checkout = active;
  if (!checkout || !checkout.api || !checkout.bootstrap) return;

  checkout.modal.setChannelLoading(channel, true);
  checkout.modal.renderCheckout(
    checkout.bootstrap,
    checkout.options.channels,
    checkout.machine.context.status,
  );

  try {
    const response = await checkout.api.updatePaymentChannel(
      checkout.reference,
      backendChannelFor(channel),
    );
    if (active !== checkout) return;

    assertSuccessfulEnvelope(response.data);
    checkout.bootstrap = mergeBootstrapPayload(
      checkout.bootstrap,
      response.data,
    );
    checkout.machine.context.bootstrap = checkout.bootstrap;
  } catch (error) {
    const payload = toErrorPayload(error);
    callErrorOnce(payload);
  } finally {
    if (active === checkout && checkout.bootstrap) {
      checkout.modal.setChannelLoading(channel, false);
      checkout.modal.renderCheckout(
        checkout.bootstrap,
        checkout.options.channels,
        checkout.machine.context.status,
      );
    }
  }
}

function beginActiveStatusChecks(): void {
  const checkout = active;
  if (!checkout || !checkout.bootstrap || checkout.machine.isTerminal()) return;

  startPolling(getPollDelay(checkout.bootstrap));
}

function handleCardFrameMessage(event: MessageEvent): void {
  const checkout = active;
  if (!checkout || !isTrustedCardFrameOrigin(event.origin)) return;

  const data = event.data as
    | {
        source?: string;
        event?: string;
        reference?: string;
        message?: string;
      }
    | undefined;
  if (data?.source !== "payisland-card-frame") return;
  if (data.reference && data.reference !== checkout.reference) return;

  if (data.event === "card.started") {
    checkout.machine.context.selectedChannel = "card";
    checkout.poller.stop();
  }

  if (data.event === "card.finished") {
    checkout.machine.context.selectedChannel = "card";
    checkout.poller.stop();
    void verifyCardFrameCompletion(checkout);
  }

  if (data.event === "card.failed") {
    callErrorOnce({
      code: "card_payment_failed",
      message: data.message || "This card payment could not be completed.",
    });
  }
}

async function verifyCardFrameCompletion(
  checkout: ActiveCheckout,
): Promise<void> {
  try {
    const payload = await verifyActive(checkout);
    if (active !== checkout) return;
    handlePayload(payload, true);
  } catch (error) {
    if (active !== checkout) return;
    callErrorOnce(toErrorPayload(error));
  }
}

function isTrustedCardFrameOrigin(origin: string): boolean {
  try {
    const url = new URL(origin);
    return (
      (url.protocol === "https:" &&
        (url.hostname === "checkout.payislands.com" ||
          url.hostname === "app-demo.payislands.com" ||
          url.hostname === "checkout-demo.payislands.com")) ||
      url.hostname === "localhost" ||
      url.hostname === "127.0.0.1"
    );
  } catch {
    return false;
  }
}

function startPolling(delay: number): void {
  const checkout = active;
  if (!checkout || !checkout.api) return;

  checkout.poller.start(
    () => verifyActive(checkout),
    (payload) => handlePayload(payload, true),
    delay,
  );
}

async function refreshActiveStatus(): Promise<void> {
  const checkout = active;
  if (!checkout || !checkout.api) return;

  checkout.poller.stop();
  checkout.modal.setStatusRefreshing(true);

  try {
    const payload = await verifyActive(checkout);
    if (active !== checkout) return;
    handlePayload(payload, true);

    if (!checkout.machine.isTerminal()) {
      startPolling(getPollDelay(payload));
    }
  } catch {
    if (active === checkout && !checkout.machine.isTerminal()) {
      startPolling(5000);
    }
  } finally {
    if (active === checkout) checkout.modal.setStatusRefreshing(false);
  }
}

async function verifyActive(
  checkout: ActiveCheckout,
): Promise<VerificationPayload> {
  if (!checkout.api) return {};

  if (
    checkout.modal.getSelectedChannel() === "bank-transfer" &&
    extractBankTransfer(checkout.bootstrap)
  ) {
    try {
      const response = await checkout.api.verifyBankTransfer(
        checkout.reference,
      );
      return response.data;
    } catch {
      const response = await checkout.api.verify(checkout.reference);
      return response.data;
    }
  }

  const response = await checkout.api.verify(checkout.reference);
  return response.data;
}

function handlePayload(
  payload: BootstrapPayload | VerificationPayload,
  fromPoll: boolean,
): void {
  const checkout = active;
  if (!checkout) return;

  const status = normalizeStatus(extractStatus(payload));
  const transaction = extractTransaction(payload);

  if (status === "success") {
    checkout.poller.stop();
    checkout.machine.send({ type: "SUCCESS" });
    if (!checkout.successCalled) {
      checkout.successCalled = true;
      checkout.options.onSuccess?.(transaction);
    }
    close(false);
    navigateToReceiptPage(checkout, transaction);
    return;
  }

  if (status === "expired") {
    checkout.poller.stop();
    checkout.machine.send({ type: "EXPIRE" });
    checkout.modal.renderExpired();
    callErrorOnce({
      code: "payment_expired",
      message: "This checkout has expired. Please start a new payment.",
    });
    return;
  }

  if (status === "failed") {
    checkout.poller.stop();
    checkout.machine.send({ type: "FAIL" });
    checkout.modal.renderFailure("This payment could not be completed.");
    callErrorOnce({
      code: "payment_failed",
      message: "This payment could not be completed.",
    });
    return;
  }

  if (fromPoll) {
    checkout.machine.send({ type: "PENDING" });
    if (checkout.modal.getSelectedChannel() === "card") {
      // Keep the hosted card frame mounted while background verification runs.
      // Re-rendering here recreates the iframe and interrupts in-frame 3DS/OTP flows.
    } else if (checkout.bootstrap) {
      checkout.modal.renderCheckout(
        checkout.bootstrap,
        checkout.options.channels,
        extractStatus(payload) ?? status,
      );
    } else {
      checkout.modal.renderPending(payload as VerificationPayload);
    }
    checkout.options.onPending?.(payload as VerificationPayload);
  } else {
    checkout.machine.send({ type: "READY" });
  }
}

function callErrorOnce(payload: CheckoutErrorPayload): void {
  const checkout = active;
  if (!checkout || checkout.errorCalled) return;
  checkout.errorCalled = true;
  checkout.options.onError?.(payload);
}

function navigateToReceiptPage(
  checkout: ActiveCheckout,
  transaction: TransactionPayload,
): void {
  if (typeof window === "undefined") return;

  const reference =
    typeof transaction.reference === "string" && transaction.reference.trim()
      ? transaction.reference
      : checkout.reference;
  const url = new URL(
    "/payment-status",
    checkout.options.__receiptBaseUrl ?? "https://checkout.payislands.com",
  );
  url.searchParams.set("reference", reference);
  url.searchParams.set("status", "success");
  if (checkout.machine.context.checkoutToken) {
    url.searchParams.set(
      "checkout_token",
      checkout.machine.context.checkoutToken,
    );
  }

  const navigate =
    checkout.options.__navigate ??
    ((target: string) => window.location.assign(target));
  navigate(url.toString());
}

function backendChannelFor(channel: string): string {
  return channel === "card" ? "card" : channel;
}

function assertSuccessfulEnvelope(payload: BootstrapPayload): void {
  const envelope = payload as Record<string, unknown>;
  if (envelope.status !== false) return;

  throw new CheckoutError({
    code: "payment_channel_update_failed",
    message:
      typeof envelope.message === "string" && envelope.message.trim()
        ? envelope.message
        : "We could not set up this payment method.",
  });
}

function mergeBootstrapPayload(
  current: BootstrapPayload,
  update: BootstrapPayload,
): BootstrapPayload {
  const currentTransaction = extractTransaction(current);
  const updateTransaction = extractTransaction(update);
  const currentFee =
    currentTransaction.fee ?? currentTransaction.transaction_fee;
  const updateAmountLooksPayableTotal =
    updateTransaction.amount !== undefined &&
    updateTransaction.amount_to_be_paid === undefined &&
    updateTransaction.amountToBePaid === undefined &&
    updateTransaction.transaction_fee === undefined &&
    updateTransaction.fee === undefined &&
    currentFee !== undefined;
  const normalizedUpdate = updateAmountLooksPayableTotal
    ? {
        ...updateTransaction,
        amount: currentTransaction.amount,
        amount_to_be_paid: updateTransaction.amount,
      }
    : updateTransaction;

  return {
    ...current,
    data: {
      ...currentTransaction,
      ...normalizedUpdate,
    },
  };
}

function renderValidationError(
  options: PayIslandCheckoutOptions | undefined,
  error: CheckoutErrorPayload,
): void {
  const modal = new CheckoutModal({
    container: options?.container,
    theme: options?.theme ?? {},
    onClose: (reason) => close(reason === "user"),
    onRetry: () => undefined,
    onChannelSelected: () => undefined,
    onPaymentStarted: () => undefined,
    onRefreshStatus: () => undefined,
  });
  const machine = new CheckoutStateMachine({
    reference: "",
    theme: options?.theme ?? {},
    status: "failed",
  });
  active = {
    options: options ?? { reference: "" },
    reference: "",
    modal,
    poller: new VerificationPoller(),
    machine,
    successCalled: false,
    errorCalled: true,
    closeCalled: false,
  };
  modal.mount();
  modal.renderError(error, false);
}

function toErrorPayload(error: unknown): CheckoutErrorPayload {
  if (error instanceof CheckoutError) return error.toPayload();
  return {
    code: "checkout_error",
    message: "We could not continue with this checkout.",
  };
}

const PayIslandCheckout = { open, close };

declare global {
  interface Window {
    PayIslandCheckout?: typeof PayIslandCheckout;
  }
}

if (typeof window !== "undefined") {
  window.PayIslandCheckout = PayIslandCheckout;
}

export default PayIslandCheckout;
